const catalog=BAHR_DATA.catalog, byId=new Map(catalog.map((r,i)=>[r.id,{...r,index:i}]));
const KEY='gnamma-bahr-vol1-', defaults={tier:'reading',focus:'normal',structure:'headings',scope:'passage',ar:true,en:true,order:'ar',marks:'source',enSize:20,arSize:28,leading:1.85,theme:'horizon',markers:true,topic:'all'};
function readStore(k,f){try{return JSON.parse(localStorage.getItem(KEY+k))??f;}catch{return f;}}
