for(const [k,values] of Object.entries({tier:['reading','study','scholarly'],focus:['normal','quiet','immersive'],structure:['headings','prose'],scope:['passage','continuous'],order:['ar','en'],marks:['source','unvowelled'],theme:['horizon','light','night','manuscript','system']}))if(!values.includes(prefs[k]))prefs[k]=defaults[k];
