function visiblePlace(){if(view!=='read')return null;const elements=$$('.passage [data-anchor]');let el=elements.find(x=>x.getBoundingClientRect().bottom>110&&x.getBoundingClientRect().width>0);if(!el)el=$('.passage');if(!el)return null;const unit=el.closest('.passage');return{r:unit?.dataset.record||current,anchor:el.id,offset:el.getBoundingClientRect().top,lang:el.closest('[data-lang]')?.dataset.lang||'en'};}
