function applyPrefs(){let theme=prefs.theme;if(theme==='system')theme=matchMedia('(prefers-color-scheme:dark)').matches?'night':'horizon';document.documentElement.dataset.theme=theme;for(const [k,v] of Object.entries({'--en-size':prefs.enSize+'px','--ar-size':prefs.arSize+'px','--leading':prefs.leading}))document.documentElement.style.setProperty(k,v);document.body.classList.remove('tier-reading','tier-study','tier-scholarly','focus-normal','focus-quiet','focus-immersive');document.body.classList.add('tier-'+prefs.tier,'focus-'+(view==='read'?prefs.focus:'normal'));document.body.classList.toggle('no-ar',!prefs.ar);document.body.classList.toggle('no-en',!prefs.en);document.body.classList.toggle('en-first',prefs.order==='en');document.body.classList.toggle('continuous-prose',prefs.structure==='prose');document.body.classList.toggle('markers-off',!prefs.markers);$$('[data-language]').forEach(x=>x.setAttribute('aria-pressed',String(prefs[x.dataset.language])));if($('#focus-label'))$('#focus-label').textContent=prefs.focus[0].toUpperCase()+prefs.focus.slice(1);window.BahrUI?.sync();$$('[data-tier]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.tier===prefs.tier)));}
