$('#previous').addEventListener('click',e=>{if(e.currentTarget.dataset.target)location.hash=readURL(e.currentTarget.dataset.target);});$('#next').addEventListener('click',e=>{if(e.currentTarget.dataset.target)location.hash=readURL(e.currentTarget.dataset.target);});
