if('serviceWorker'in navigator&&location.protocol!=='file:'){navigator.serviceWorker.register('sw.js').catch(()=>{});navigator.serviceWorker.addEventListener('message',e=>{const d=e.data;if(d.type==='OFFLINE_PROGRESS'&&$('#offline-status'))$('#offline-status').textContent=d.done+' / '+d.total+' files saved for offline use…';if(d.type==='OFFLINE_DONE'){$('#offline-status')&&($('#offline-status').textContent=d.failed?'Some files could not be saved. Reconnect and retry to finish offline setup.':'The complete reader is saved on this device. PDF downloads are separate.');toast(d.failed?'Offline setup needs a retry.':'The complete reader is ready offline.');}});}
